function regionErrors(region){if(region===null||region===undefined)return [];if(typeof region!=='object')return ['Vùng sửa không hợp lệ'];if(['x','y','width','height'].some(k=>!Number.isFinite(region[k])))return ['Vùng sửa không hợp lệ'];if(region.x<0||region.y<0||region.width<.015||region.height<.015||region.x+region.width>1.00001||region.y+region.height>1.00001)return ['Vùng sửa phải nằm trong ảnh và có kích thước tối thiểu 1,5%'];return []}
function regionPixels(region,width,height){const errors=regionErrors(region);if(errors.length||!region)throw Error(errors[0]||'Chọn vùng cần sửa');const left=Math.max(0,Math.floor(region.x*width)),top=Math.max(0,Math.floor(region.y*height));return {left,top,width:Math.max(1,Math.min(width-left,Math.ceil(region.width*width))),height:Math.max(1,Math.min(height-top,Math.ceil(region.height*height)))}}
function regionPrompt(region){if(!region)return '';const e=regionErrors(region);if(e.length)throw Error(e[0]);return 'FOCUSED REPAIR REGION: normalized coordinates in the ORIGINAL full image: left '+(region.x*100).toFixed(1)+'%, top '+(region.y*100).toFixed(1)+'%, width '+(region.width*100).toFixed(1)+'%, height '+(region.height*100).toFixed(1)+'%. The supplementary enlarged crop is a close-up extracted from this exact source region, NOT a different subject or composition. Inspect its small defects carefully. Repair malformed visible features within this region while preserving the original identity and the surrounding intact evidence. The output MUST be the full original image with corrections integrated at this position, not a standalone crop. Preserve every region outside the selection; blend repaired edges naturally. This is a visual region instruction, not a provider pixel mask; do not claim pixel-locked inpainting.'}
module.exports={regionErrors,regionPixels,regionPrompt};
